I wrote a simple parallel post order traversal algorithm with OpenMP in C++. #include <string.h>
#include <omp.h>
#define NUM_THREADS 16

struct node {
    node* left;
    node* right;
    int value;
};

void traverseParallelAux(node* cur) {

    if (cur->left != NULL)
        #pragma omp task firstprivate(cur)
        traverseParallelAux(cur->left);

    if (cur->right != NULL)
        #pragma omp task firstprivate(cur)
        traverseParallelAux(cur->right);

    std::string output = std::to_string(cur->value);
    output.append(" ");

    #pragma omp taskwait 
    {
        #pragma omp critical
        {
            std::cout << output;
        }
    }   
}

void traverseParallel(node* cur) {

    #pragma omp parallel num_threads(NUM_THREADS)
    {
        #pragma omp single nowait
        {
            traverseParallelAux(cur);   
