answers.body:
The code you are trying to parallelize is just not expensive enough, making the overhead of the parallelization comparable to the gain. If you add some artificial workload in the loop by sleeping for a short amount of time, you can see the performance gain: #include <chrono>
#include <thread>
#include <Rcpp.h>
// [[Rcpp::plugins(openmp)]]
#include <omp.h>
// [[Rcpp::depends(RcppParallel)]]
#include <RcppParallel.h>

// [[Rcpp::export]]
Rcpp::NumericVector parallel_sleep(int n, int ncores) {

  Rcpp::NumericVector res_(n);
  RcppParallel::RVector<double> res(res_);

#pragma omp parallel num_threads(ncores)
{
#pragma omp for
  for (int j = 0; j < n; ++j) {
    double lres(0);
    std::this_thread::sleep_for(std::chrono::microseconds(10));
    lres += j;
    res[j] = lres / n;
  }
}

return res_;
}

// [[Rcpp::export]]
Rcpp::NumericVector not_parallel_sleep(int n) {

  Rcpp::NumericVector res(n);

  for (int j = 0; j < n; ++j) {
    double lres(0);
    std::this_thread::sleep_for(std::chrono::microseconds(10));
    lres += j;
    res[j] = lres / n;
  }

  return res;
}

