answers.body:
As pointed in comments, you have two main problems: newRe and newIm are shared, but should not be r , gr and b 's access is not specified (shared by default I think) There is concurrent calls to QImage::setPixel To correct this, do not hesitate to make a omp for loop nested in a omp parallel block. Declare private variable just before the for loop: To prevent concurrent calls to QImage::setPixel , since this function is not thread safe , you can put it in a critical region, with #pragma omp critical . int main(int argc, char *argv[])
{
    int imageWidth=1000, imageHeight=1000, maxIterations=3000;

    double cRe = -0.7;
    double cIm = 0.27015;

    QElapsedTimer time;
    QImage img(imageHeight, imageWidth, QImage::Format_RGB888);//Qimagetesting
    img.fill(Qt::black);
    time.start();

    #pragma omp parallel
    {
        /* all folowing values will be private */
        int i,x,y;
        int r, gr, b;
        double newRe, newIm, oldRe, oldIm;

        #pragma omp for
        for(y = 0; y < imageHeight; y++)
        {            
            for(x = 0; x < imageWidth; x++)
            {
                newRe = newReal(x,imageWidth);
                newIm = newImaginary(y,imageHeight);
                i= julia(newRe, newIm, oldRe, oldIm, cRe, cIm, maxIterations);

                r = (3*i % 256);
                gr = (2*(int)sqrtf(i) % 256);
                b = (i % 256);

                #pragma omp critical
                    img.setPixel(x, y, qRgb(r, gr, b));
             }
        }
    }

    img.save("julia.png","PNG", 100);

    cout<<time.elapsed()/1000.00<<" seconds"<<endl;

    return 0;
} To go further, you can save some cpu time replacing ::setPixel by ::scanLine : #pragma omp for
    for(y = 0; y < imageHeight; y++)
    {                        
        uchar *line = img.scanLine(y);
        for(x = 0; x < imageWidth; x++)
        {
            newRe = newReal(x,imageWidth);
            newIm = newImaginary(y,imageHeight);
            i= julia(newRe, newIm, oldRe, oldIm, cRe, cIm, maxIterations);

            r = (3*i % 256);
            gr = (2*(int)sqrtf(i) % 256);
            b = (i % 256);

            *line++ = r;
            *line++ = gr;
            *line++ = b;
         }
    } EDIT: Since the julia set seems to have a central symetry around (0,0) point, you can perfom only half of calculus: int half_heigt = imageHeight / 2;
#pragma omp for

// compute only for first half of image
for(y = 0; y < half_heigt; y++)
{            
    for(x = 0; x < imageWidth; x++)
    {
        newRe = newReal(x,imageWidth);
        newIm = newImaginary(y,imageHeight);
        i= julia(newRe, newIm, oldRe, oldIm, cRe, cIm, maxIterations);

        r = (3*i % 256);
        gr = (2*(int)sqrtf(i) % 256);
        b = (i % 256);

        #pragma omp critical
        {
            // set the point  
            img.setPixel(x, y, qRgb(r, gr, b));

            // set the symetric point
            img.setPixel(imageWidth-1-x, imageHeight-1-y, qRgb(r, gr, b));
        }
     }
}

