                    }
                }
            }
        }

        /* STEP 3: add elements of matrices d=a+b */
        #pragma omp section 
        {
            #pragma omp parallel for private(i,j) schedule(runtime)
            for (i=0; i<N; i++) {
                for(j=0; j<N; j++) {
                    d[i][j] = a[i][j] + b[i][j];
                }
            }

        }
      }


  end_t = clock();
  time_stop = time(NULL);
  total_t = (double)(end_t - start_t) / CLOCKS_PER_SEC *1000.0;
  printf("Threads number is : %d. \n",nthreads);
  printf("Total time taken by CPU: %0.2f seconds. \n", total_t  );
  printf("Task time is about %0.0f seconds for matrix size equals to  %d \n",difftime(time_stop,time_start),N);
  printf ("Done.\n");
  exit(0);
} note: I used runtime schedule policy, because I need to do it customizable by OMP_SCHEDULE  environment variable. Thanks in advance!

