     } This update takes around 60 seconds for each process. 
Now with Hybrid MPI, I run two processes (1 process per socket --bind-to socket --map-by socket and OMP_PROC_PLACES=cores with OMP_PROC_BIND=close ). I create 12 threads per MPI Process (i.e. 12 threads per socket or processor). Now each MPI process has an array of size : 192/2 x 192 x 192 = 96x192x192 elements. Each thread works on 96/12 x 192 x 192 = 8 x 192 x 192 portion of the array owned by each process. I do the same triple loop update using threads but the time is approximately 76 seconds for each thread. The load balance is perfect in both the problems. What could be the possible causes of performance degradation ? Is is False Sharing because threads could be invalidating the cache lines close to each other's chunk of data ? If yes, then how do I reduce this performance degradation ? (I have purposefully not mentioned ghost data but initially I am NOT overlapping communication with computation.) In response to the comments below, am posting the code. Apologies for the long MWE but you can very safely ignore (1) Header files declaration (2) Variable Declaration (3) Memory allocation routine (4) Formation of Cartesian Topology (5) Setting boundary conditions in parallel using OpenMP parallel region (6) Declaration of MPI_Type_subarray datatype (7) MPI_Isend() and MPI_Irecv() calls and just concentrate on (a) INDEPENDENT UPDATE OpenMP parallel region (b) independent_update(...) routine being called from here. /* IGNORE THIS PORTION */
#include<mpi.h>
#include<omp.h>


#include<stdio.h>
#include<stdlib.h>
#include<math.h>


#define MIN(a,b) (a < b ? a : b)
#define Tol 0.00001

 /* IGNORE THIS ROUTINE */
void input(int *X, int *Y, int *Z)
{
    int a=193, b=193, c=193;
    *X = a;
    *Y = b;
    *Z = c;
}
 /* IGNORE THIS ROUTINE */
float*** allocate_mem(int X, int Y, int Z)
{
    int i,j;
    float ***matrix;
    float *arr;

    arr = (float*)calloc(X*Y*Z, sizeof(float));

    matrix = (float***)calloc(X, sizeof(float**));

    for(i = 0 ; i<= X-1; i++)
        matrix[i] = (float**)calloc(Y, sizeof(float*));

    for(i = 0 ; i <= X-1; i++)
        for(j=0; j<= Y-1; j++)
            matrix[i][j] = &(arr[i*Y*Z + j*Z]); 

    return matrix ; 
}

/* THIS ROUTINE IS IMPORTANT */

float independent_update(float ***old, float ***new, int NX, int NY, int NZ, int tID, int chunk)
{
    int i,j,k, start, end;
    float error = 0.0; 
    float diff;


        start = tID * chunk + 1;
        end = MIN( (tID+1)*chunk, NX-2 ); 

        for(i = start; i <= end ; i++)
        {
            for(j = 1; j<= NY-2; j++)
            {
                #pragma omp simd
                for(k = 1; k<= NZ-2; k++)
                {
                    new[i][j][k] = (1/6.0) *(old[i-1][j][k] + old[i+1][j][k] + old[i][j-1][k] + old[i][j+1][k] + old[i][j][k-1] + old[i][j][k+1] );
                    diff = 1.0 - new[i][j][k]; 
                    diff = (diff > 0 ? diff : -1.0 * diff ); 
                    if(diff > error)
                        error = diff;
                }
            }
        }   
    return error;  

}


int main(int argc, char *argv[])
{

    /* IGNORE VARIABLE DECLARATION */
