    local_z[0] = PX;
    local_z[1] = PY;
    local_z[2] = 1;

    MPI_Type_create_subarray(ndims, gsize, local_z, start, MPI_ORDER_C, MPI_FLOAT, &z_subarray);
    MPI_Type_commit(&z_subarray); 

    t_setup_end = MPI_Wtime(); 

    strt = MPI_Wtime();

while(G_max_err > Tol) //iterations < ITERATIONS)
{

    iterations++ ; 


    t_comm_strt = MPI_Wtime();

