  // array helpers
  int leftLengths[THREADS] = {0};
  int offsetLeft[THREADS] = {0};
  int rightLengths[THREADS] = {0};
  int offsetRight[THREADS] = {0};
  int splitIdxs[THREADS] = {0};

  /////////////////////////////
  // PARALLEL PARTITION PHASE
  /////////////////////////////
  #pragma omp parallel num_threads(THREADS)
  {
      // number of thread
      int n = omp_get_thread_num();

      // pivot - common for all threads
      int pivot = arr[l];

      // calculate range for thread - data that this thread will be working on
      int currentThreadL = l + elementsPerThread * n;
      int currentThreadR = n == THREADS-1 ? r : l + elementsPerThread * (n+1) - 1;

      // precise number of elements that will be used by thread
