    // precise number of elements that will be used by thread
    int threadElements = (currentThreadR - currentThreadL + 1);

    // merge left parts
    memcpy(tmpArray + offsetLeft[n], arr + currentThreadL, (splitIdxs[n] - currentThreadL) * sizeof(int));

    // merge right parts
    memcpy(tmpArray + masterSplitIdx + offsetRight[n], arr + splitIdxs[n], (currentThreadR - splitIdxs[n] + 1) * sizeof(int));

    #pragma omp barrier

    // copy back to original array
        memcpy(arr + currentThreadL, tmpArray + elementsPerThread * n, threadElements * sizeof(int));
    }

    // cleanup
