      #pragma omp parallel for reduction(min : shortest_dist) num_threads(nb)
      for (int i = 0; i < num_nodes; i++){
          // find nearest node
          if ( !tree[i] && min_distance[i] < shortest_dist ){
              shortest_dist = min_distance[i];
