In this solution the error is controlled by the foundError boolean which is modified ASAP the error is found and prevents threads picking other iterations to continue processing. The #pragma omp flush ensures that the modifications to the boolen variable is sent to main memory as soon as it is modified or before reading. This is based from the solution discussed in http://www.thinkingparallel.com/2007/06/29/breaking-out-of-loops-in-openmp .
Notice also, that the solution needs a detailed study of which variables should be privatized or kept shared in the #pragma omp parallel for bool foundError = false;

    #pragma omp parallel for
    for (long int i = 0; i < totalLoopingCount_Operands-1; i++) {

        #pragma omp flush(foundError)
        if (!foundError)
        {
            if (operands[operationSequence[0]] == '*' || operands[operationSequence[0]] == '/') {
                operationSequence[0]++;
                continue;
            }
            string checkResult = checkAnswer(targetAnswer, operands, question, operationSequence);  //Check the current equation
            //check redundant answer
            for (vector<string>::iterator it = answer.begin(); it != answer.end();it++) {
                if (*it == checkResult) {
                     isRedundantAnswer = true;
                }
            }
            //if result == -1, means this is not a solution
            if (checkResult != "-1" && !isRedundantAnswer) {
                answer.push_back(checkResult);  //insert the answer into the list
            }
            //increment the operationSequence will change the equation
            operationSequence[0]++;
            for (int j = 0; j < question.size() - 1; j++) {
                if (operationSequence[j] == operands.size()) {
                    operationSequence[j] = 0;
                    operationSequence[j + 1] ++;
                }
            }
            if (operationSequence[i % (question.size() - 1)] == 5) {
               foundError = true;
               #pragma omp flush(foundError)
            }
        }
    }
    if (foundError) {
        cout << "error" << endl;
    }

